    private readonly ICurrentTenant _tenant; private readonly ICurrentUser _user; private readonly IModuloLicenciamentoService _modulos; private readonly IPermissionService _permissoes; private readonly IAuditService _audit; private readonly ISaneamentoSequencialService _seq; private readonly IHostEnvironment _env; private readonly ILogger<SaneamentoService> _logger;
    private readonly ISaneamentoConsumidorRepository _consumidores; private readonly ILigacaoSaneamentoRepository _ligacoes; private readonly IUnidadeConsumidoraRepository _unidades; private readonly IHidrometroRepository _hidrometros; private readonly ILeituraConsumoRepository _leituras; private readonly IFaturaSaneamentoRepository _faturas; private readonly IArrecadacaoSaneamentoRepository _arrecadacoes; private readonly IParcelamentoSaneamentoRepository _parcelamentos; private readonly IOrdemServicoSaneamentoRepository _ordens; private readonly IEquipeCampoSaneamentoRepository _equipes; private readonly ILaboratorioSaneamentoRepository _laboratorio; private readonly IRedeSaneamentoRepository _rede; private readonly ISaneamentoDashboardRepository _dashboard; private readonly ISaneamentoExportacaoRepository _exportacao;
    public SaneamentoService(ICurrentTenant tenant, ICurrentUser user, IModuloLicenciamentoService modulos, IPermissionService permissoes, IAuditService audit, ISaneamentoSequencialService seq, IHostEnvironment env, ILogger<SaneamentoService> logger, ISaneamentoConsumidorRepository consumidores, ILigacaoSaneamentoRepository ligacoes, IUnidadeConsumidoraRepository unidades, IHidrometroRepository hidrometros, ILeituraConsumoRepository leituras, IFaturaSaneamentoRepository faturas, IArrecadacaoSaneamentoRepository arrecadacoes, IParcelamentoSaneamentoRepository parcelamentos, IOrdemServicoSaneamentoRepository ordens, IEquipeCampoSaneamentoRepository equipes, ILaboratorioSaneamentoRepository laboratorio, IRedeSaneamentoRepository rede, ISaneamentoDashboardRepository dashboard, ISaneamentoExportacaoRepository exportacao)
