    private async Task<Result<(long TenantId,long EntidadeId,long? ExercicioId,long? UsuarioId)>> Ctx(string recurso,string acao,CancellationToken ct){ if(!_tenant.TenantId.HasValue||!_tenant.EntidadeId.HasValue)return Result<(long,long,long?,long?)>.Failure("Tenant e entidade são obrigatórios."); if(!await _modulos.IsModuleEnabledAsync(_tenant.TenantId.Value,SaneamentoPermissoes.Modulo,ct).ConfigureAwait(false))return Result<(long,long,long?,long?)>.Failure("Módulo saneamento não contratado ou desabilitado para o tenant."); if(_user.UsuarioId.HasValue&&!await _permissoes.HasPermissionAsync(_user.UsuarioId.Value,"saneamento",recurso,acao,ct).ConfigureAwait(false))return Result<(long,long,long?,long?)>.Failure("Usuário sem permissão para saneamento."); return Result<(long,long,long?,long?)>.Success((_tenant.TenantId.Value,_tenant.EntidadeId.Value,_tenant.ExercicioId,_user.UsuarioId)); }
    private static int Page(int p)=>p<=0?1:p; private static int Size(int s)=>s is <=0 or >100?20:s;

    async Task<Result<PagedResult<SaneamentoConsumidorResponse>>> ISaneamentoConsumidorService.ListarAsync(SaneamentoConsumidorFiltro f,CancellationToken ct){var c=await Ctx("consumidor","visualizar",ct); if(c.IsFailure)return Result<PagedResult<SaneamentoConsumidorResponse>>.Failure(c.Error!); var v=c.Value!; return Result<PagedResult<SaneamentoConsumidorResponse>>.Success(await _consumidores.ListarAsync(v.TenantId,v.EntidadeId,f with{Page=Page(f.Page),PageSize=Size(f.PageSize)},ct));}
    async Task<Result<SaneamentoConsumidorResponse>> ISaneamentoConsumidorService.ObterAsync(long id,bool completo,CancellationToken ct){var c=await Ctx("consumidor",completo?"visualizar_dados_completos":"visualizar",ct); if(c.IsFailure)return Result<SaneamentoConsumidorResponse>.Failure(c.Error!); var v=c.Value!; var item=await _consumidores.ObterAsync(v.TenantId,v.EntidadeId,id,completo,ct); await _audit.RegistrarAsync("saneamento","ACESSO_DADO_PESSOAL","sigov.saneamento_consumidor",id.ToString(),null,new{id,completo},ct); return item is null?Result<SaneamentoConsumidorResponse>.Failure("Consumidor não encontrado."):Result<SaneamentoConsumidorResponse>.Success(item);}
    async Task<Result<long>> ISaneamentoConsumidorService.CriarAsync(SaneamentoConsumidorCreateRequest r,CancellationToken ct){var c=await Ctx("consumidor","criar",ct); if(c.IsFailure)return Result<long>.Failure(c.Error!); var v=c.Value!; try{ _=new SaneamentoConsumidor(v.TenantId,v.EntidadeId,r.PessoaId,r.CodigoConsumidor??"CON"); var codigo=r.CodigoConsumidor??await _seq.ProximoAsync(v.TenantId,v.EntidadeId,"CON",ct); var id=await _consumidores.CriarAsync(v.TenantId,v.EntidadeId,v.UsuarioId,r,codigo,ct); await _audit.RegistrarAsync("saneamento","CRIAR","sigov.saneamento_consumidor",id.ToString(),null,r,ct); return Result<long>.Success(id);}catch(Exception ex){_logger.LogWarning(ex,"Falha ao criar consumidor de saneamento"); return Result<long>.Failure(ex.Message);}}
    async Task<Result> ISaneamentoConsumidorService.AtualizarAsync(long id,SaneamentoConsumidorUpdateRequest r,CancellationToken ct){var c=await Ctx("consumidor","editar",ct); if(c.IsFailure)return Result.Failure(c.Error!); var v=c.Value!; await _consumidores.AtualizarAsync(v.TenantId,v.EntidadeId,id,v.UsuarioId,r,ct); await _audit.RegistrarAsync("saneamento","ALTERAR","sigov.saneamento_consumidor",id.ToString(),null,r,ct); return Result.Success();}
    async Task<Result> ISaneamentoConsumidorService.ExcluirAsync(long id,CancellationToken ct){var c=await Ctx("consumidor","excluir",ct); if(c.IsFailure)return Result.Failure(c.Error!); var v=c.Value!; await _consumidores.ExcluirAsync(v.TenantId,v.EntidadeId,id,v.UsuarioId,ct); await _audit.RegistrarAsync("saneamento","EXCLUIR","sigov.saneamento_consumidor",id.ToString(),null,new{id},ct); return Result.Success();}

