    async Task<Result<long>> ILeituraConsumoService.CriarAsync(LeituraConsumoCreateRequest r,CancellationToken ct){var c=await Ctx("leitura","criar",ct); if(c.IsFailure)return Result<long>.Failure(c.Error!); var v=c.Value!; var tipo=Enum.TryParse<TipoLeitura>(r.TipoLeitura,true,out var parsed)?parsed:TipoLeitura.Normal; var consumo=r.LeituraAtual-r.LeituraAnterior; _=new LeituraConsumo(v.TenantId,v.EntidadeId,r.UnidadeConsumidoraId,r.LeituraAnterior,r.LeituraAtual,r.ConsumoFaturado??consumo,tipo,r.Observacao,r.Latitude,r.Longitude); var id=await _leituras.CriarAsync(v.TenantId,v.EntidadeId,v.ExercicioId,v.UsuarioId,r,consumo,r.ConsumoFaturado??consumo,ct); await _audit.RegistrarAsync("saneamento","CRIAR","sigov.saneamento_leitura",id.ToString(),null,r,ct); return Result<long>.Success(id);}
    async Task<Result<long>> ILeituraConsumoService.GerarFaturaAsync(long id,GerarFaturaPorLeituraRequest r,CancellationToken ct){var c=await Ctx("leitura","gerar_fatura",ct); if(c.IsFailure)return Result<long>.Failure(c.Error!); var v=c.Value!; var numero=await _seq.ProximoAsync(v.TenantId,v.EntidadeId,"FAT",ct); var fid=await _faturas.GerarPorLeituraAsync(v.TenantId,v.EntidadeId,v.ExercicioId,id,v.UsuarioId,r,numero,_env.EnvironmentName,ct); await _audit.RegistrarAsync("saneamento","GERAR_FATURA","sigov.saneamento_fatura",fid.ToString(),null,r,ct); return Result<long>.Success(fid);}

