    async Task<Result<long>> IFaturaSaneamentoService.CriarAsync(FaturaSaneamentoCreateRequest r,CancellationToken ct){var c=await Ctx("fatura","criar",ct); if(c.IsFailure)return Result<long>.Failure(c.Error!); var v=c.Value!; var total=r.ValorAgua+r.ValorEsgoto+r.ValorServicos+r.ValorMulta+r.ValorJuros-r.ValorDesconto; _=new FaturaSaneamento(v.TenantId,v.EntidadeId,r.UnidadeConsumidoraId,r.Numero??"FAT",total); var numero=r.Numero??await _seq.ProximoAsync(v.TenantId,v.EntidadeId,"FAT",ct); var id=await _faturas.CriarAsync(v.TenantId,v.EntidadeId,v.ExercicioId,v.UsuarioId,r,numero,total,_env.EnvironmentName,ct); await _audit.RegistrarAsync("saneamento","CRIAR","sigov.saneamento_fatura",id.ToString(),null,r,ct); return Result<long>.Success(id);}
