    async Task<Result<ArrecadacaoSaneamentoResponse>> IFaturaSaneamentoService.RegistrarPagamentoDevAsync(long id,RegistrarPagamentoDevRequest r,CancellationToken ct){ if(!_env.IsDevelopment())return Result<ArrecadacaoSaneamentoResponse>.Failure("Pagamento manual/dev bloqueado fora de Development."); var c=await Ctx("fatura","registrar_pagamento_dev",ct); if(c.IsFailure)return Result<ArrecadacaoSaneamentoResponse>.Failure(c.Error!); var v=c.Value!; var numero=await _seq.ProximoAsync(v.TenantId,v.EntidadeId,"ARR-SAN",ct); var res=await _faturas.RegistrarPagamentoDevAsync(v.TenantId,v.EntidadeId,v.ExercicioId,id,v.UsuarioId,r,numero,ct); await _audit.RegistrarAsync("saneamento","ARRECADAR_DEV","sigov.saneamento_arrecadacao",res.Id.ToString(),null,r,ct); return Result<ArrecadacaoSaneamentoResponse>.Success(res);}

